"use client"

import type { PartitionResult } from "@/components/viewers/lib/partition-types"
import { PartitionViewer } from "@/components/viewers/partition/partition-viewer"
import { PdfViewer } from "@/components/ui/pdf-viewer"

const PDF_URL = "/samples/attention.pdf"

// A partition result: keyed chunks, each owning a set of 1-indexed pages.
const PARTITION_RESULT: PartitionResult = {
  output: [
    { key: "abstract", pages: [1] },
    { key: "introduction", pages: [2] },
    { key: "model_architecture", pages: [2, 3, 4, 5, 6] },
    { key: "training", pages: [7, 8] },
    { key: "results", pages: [8, 9, 10] },
    { key: "references", pages: [10, 11, 12] },
  ],
  consensus: { choices: [], likelihoods: null },
  usage: null,
}

/**
 * Partition viewer block — the file + legend + waterfall ribbon over keyed
 * chunks. `PartitionViewer` owns the chrome (legend + horizontal page ribbon)
 * and renders it below the `PdfViewer` toolbar.
 */
export function PartitionViewerBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <PartitionViewer
        result={PARTITION_RESULT}
        renderDocument={(handlers) => (
          <PdfViewer
            src={PDF_URL}
            bare
            downloadFileName="attention.pdf"
            header={handlers.header}
            onVisiblePageChange={handlers.onCurrentPageChange}
            onScrollProgressChange={handlers.onScrollProgressChange}
            className="h-full"
          />
        )}
      />
    </div>
  )
}

"use client";

import { useCallback, useMemo, useRef, useState, type ReactNode } from "react";
import { Key, Loader2 } from "lucide-react";

import type {
  PartitionChunk,
  PartitionResult,
} from "@/components/viewers/lib/partition-types";
import { type Segment, buildColorMap } from "@/lib/segments";
import { SegmentLegend } from "@/components/ui/segment-legend";
import { PageRibbon, type RibbonRow } from "@/components/ui/page-ribbon";

/**
 * Handlers a document surface receives. `header` (legend + waterfall) is the
 * viewer's chrome — the surface renders it below the document toolbar.
 */
export interface PartitionDocumentHandlers {
  onCurrentPageChange: (page: number) => void;
  onScrollProgressChange: (progress: number) => void;
  header: ReactNode;
}

export interface PartitionViewerProps {
  result: PartitionResult | null;
  isProcessing?: boolean;
  renderDocument?: (handlers: PartitionDocumentHandlers) => ReactNode;
}

export function PartitionViewer({
  result,
  isProcessing = false,
  renderDocument,
}: PartitionViewerProps) {
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [activeId, setActiveId] = useState<string | null>(null);
  const previewPanelRef = useRef<HTMLDivElement | null>(null);
  const hasOutput = !!result && result.output.length > 0;

  const voteChoices = useMemo(
    () => result?.consensus.choices ?? [],
    [result?.consensus.choices],
  );

  const pageCount = useMemo(() => {
    if (!result) return 0;
    const lastPage = (chunks: PartitionChunk[]) =>
      chunks.reduce(
        (max, c) => Math.max(max, c.pages.length ? c.pages[c.pages.length - 1] : 0),
        0,
      );
    return Math.max(
      lastPage(result.output),
      voteChoices.reduce((m, chunks) => Math.max(m, lastPage(chunks)), 0),
    );
  }, [result, voteChoices]);

  const { legendSegments, rows } = useMemo(() => {
    if (!result) return { legendSegments: [] as Segment[], rows: [] as RibbonRow[] };
    const colors = buildColorMap([
      ...result.output.map((c) => c.key),
      ...voteChoices.flat().map((c) => c.key),
    ]);
    const seg = (c: PartitionChunk): Segment => ({
      id: c.key,
      label: c.key,
      pages: [...c.pages].sort((a, b) => a - b),
      color: colors.get(c.key) ?? "var(--color-muted-foreground)",
      index: 0,
    });
    const legendByKey = new Map<string, Segment>();
    for (const c of result.output) {
      const existing = legendByKey.get(c.key);
      legendByKey.set(
        c.key,
        existing ? { ...existing, pages: [...existing.pages, ...c.pages] } : seg(c),
      );
    }
    const ribbonRows: RibbonRow[] = [
      ...result.output.map((c, i) => ({ id: `c-${i}`, segments: [seg(c)] })),
      ...voteChoices.flatMap((chunks, vi) =>
        chunks.map((c, i) => ({ id: `v${vi}-${i}`, segments: [seg(c)] })),
      ),
    ];
    return { legendSegments: [...legendByKey.values()], rows: ribbonRows };
  }, [result, voteChoices]);

  const handleJumpToPage = useCallback((page: number) => {
    previewPanelRef.current
      ?.querySelector<HTMLElement>(`[data-page-number="${page}"]`)
      ?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  const currentPageInt = Math.max(1, Math.floor(currentPdfPage));

  if (!hasOutput) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center gap-4 bg-muted px-8 text-muted-foreground">
        {isProcessing ? (
          <>
            <Loader2 className="h-12 w-12 animate-spin text-primary" />
            <p className="text-center text-base text-muted-foreground">Partitioning...</p>
          </>
        ) : (
          <>
            <Key className="h-16 w-16 text-muted-foreground" />
            <p className="text-center text-base text-muted-foreground">
              Run partition to see output
            </p>
            <p className="max-w-sm text-center text-sm text-muted-foreground">
              Upload a document, set a key and instructions, then click Run
              Partition
            </p>
          </>
        )}
      </div>
    );
  }

  const header = (
    <SegmentLegend
      segments={legendSegments}
      currentPage={currentPageInt}
      activeId={activeId}
      onActivate={setActiveId}
      onSelect={(id) => {
        const seg = legendSegments.find((s) => s.id === id);
        if (seg?.pages.length) handleJumpToPage(seg.pages[0]);
      }}
      columns={4}
      accessory={
        <PageRibbon
          orientation="horizontal"
          rows={rows}
          pageCount={pageCount}
          currentPage={currentPageInt}
          scrollProgress={scrollProgress}
          activeId={activeId}
          onActivate={setActiveId}
          onSelectPage={handleJumpToPage}
        />
      }
    />
  );

  return (
    <div ref={previewPanelRef} className="flex min-h-0 flex-1 flex-col bg-background">
      {renderDocument ? (
        renderDocument({
          onCurrentPageChange: setCurrentPdfPage,
          onScrollProgressChange: setScrollProgress,
          header,
        })
      ) : (
        <div className="flex h-full items-center justify-center">
          <span className="text-sm text-muted-foreground">No document available</span>
        </div>
      )}
    </div>
  );
}

// Partition result shapes, mirrored from the Retab API / dashboard.

export interface PartitionChunk {
  key: string
  /** 1-indexed pages assigned to this chunk. */
  pages: number[]
}

export interface PartitionChunkLikelihood {
  key: number | null
  pages: number[]
}

export interface PartitionConsensus {
  choices: PartitionChunk[][]
  likelihoods: PartitionChunkLikelihood[] | null
}

export interface PartitionUsage {
  credits: number
}

export interface PartitionResult {
  output: PartitionChunk[]
  consensus: PartitionConsensus
  usage: PartitionUsage | null
}
